sparqlQuery:
PREFIX sf: <https://duo.example.nl/ontology#>
SELECT ?rule ?ruleId ?title ?description ?credentialType ?requiredClaim ?legalBasis ?isRequired ?order ?sameAsRule
WHERE {
  ?rule a sf:StudyFinanceRule ;
        sf:ruleId         ?ruleId ;
        sf:title          ?title ;
        sf:description    ?description ;
        sf:credentialType ?credentialType ;
        sf:requiredClaim  ?requiredClaim ;
        sf:legalBasis     ?legalBasis ;
        sf:isRequired     ?isRequired ;
        sf:order          ?order .
  OPTIONAL { ?rule sf:sameAsRule ?sameAsRule . }
}
ORDER BY ?order
